package com.brightloop.invoice;
import com.brightloop.payment.PaymentService;import java.io.ByteArrayOutputStream;import java.io.IOException;import java.util.*;import org.apache.pdfbox.pdmodel.*;import org.apache.pdfbox.pdmodel.common.PDRectangle;import org.apache.pdfbox.pdmodel.font.*;import org.springframework.stereotype.Service;
import com.brightloop.quotation.QuotationDtos;
@Service public class PdfService {
 public byte[] invoice(InvoiceDtos.Response invoice){return pdf("BRIGHTLOOP  |  INVOICE",new String[]{"Invoice: "+invoice.invoiceNumber(),"Customer: "+invoice.customerName()+" <"+invoice.customerEmail()+">","Issue date: "+invoice.issueDate()+"     Due date: "+invoice.dueDate(),"Billing period: "+invoice.billingPeriodStart()+" to "+invoice.billingPeriodEnd(),"","ITEMS"},invoice.lines().stream().map(l->l.description()+"  |  "+l.quantity()+" x "+money(l.unitPrice())+"  |  Tax "+money(l.taxAmount())+"  |  "+money(l.lineTotal())).toArray(String[]::new),new String[]{"","Subtotal: "+money(invoice.subtotal()),"Tax: "+money(invoice.taxAmount()),"Discount: -"+money(invoice.discountAmount()),"Invoice total: "+money(invoice.total()),"Paid: "+money(invoice.amountPaid()),"Outstanding: "+money(invoice.outstanding()),"Status: "+invoice.status()});}
 public byte[] receipt(PaymentService.Response p){return pdf("BRIGHTLOOP  |  PAYMENT RECEIPT",new String[]{"Receipt: "+p.paymentNumber(),"Invoice: "+p.invoiceNumber(),"Customer: "+p.customerName(),"Payment date: "+p.paymentDate(),"Method: "+p.paymentMethod(),"Reference: "+(p.transactionReference()==null?"—":p.transactionReference()),"","Amount paid: "+money(p.amount()),"Status: "+p.status()},new String[0],new String[]{"Thank you for your payment.","Brightloop subscription billing"});}
 public byte[] quotation(QuotationDtos.Response q){return pdf("BRIGHTLOOP  |  QUOTATION",new String[]{"Quotation: "+q.quotationNumber(),"Customer: "+q.customerName()+" <"+q.customerEmail()+">","Created: "+q.createdOn()+"     Valid until: "+q.expiresOn(),"Status: "+q.status(),"Payment terms: "+(q.paymentTerms()==null?"—":q.paymentTerms()),"","ITEMS"},q.lines().stream().map(l->l.productName()+" · "+(l.planName()==null?"One-time":l.planName())+"  |  "+l.quantity()+" x "+money(l.unitPrice())+"  |  Tax "+money(l.lineTax())+"  |  "+money(l.lineTotal())).toArray(String[]::new),new String[]{"","Subtotal: "+money(q.subtotal()),"Tax: "+money(q.taxAmount()),"Discount: -"+money(q.discountAmount()),"Quotation total: "+money(q.grandTotal()),"","Notes: "+(q.notes()==null?"—":q.notes())});}
 private byte[] pdf(String title,String[] before,String[] rows,String[] after){try(PDDocument doc=new PDDocument();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){List<String> lines=new ArrayList<>();lines.add(title);lines.add("");lines.addAll(Arrays.asList(before));lines.addAll(Arrays.asList(rows));lines.addAll(Arrays.asList(after));PDType1Font regular=new PDType1Font(Standard14Fonts.FontName.HELVETICA);PDType1Font bold=new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD);for(int offset=0;offset<lines.size();offset+=42){PDPage page=new PDPage(PDRectangle.LETTER);doc.addPage(page);try(PDPageContentStream cs=new PDPageContentStream(doc,page)){float y=744;for(int i=offset;i<Math.min(offset+42,lines.size());i++){String text=lines.get(i);boolean header=i==0||text.startsWith("Invoice total:")||text.startsWith("Outstanding:")||text.startsWith("Amount paid:");cs.beginText();cs.setFont(header?bold:regular,header?i==0?16:11:10);cs.newLineAtOffset(52,y);cs.showText(text.length()>112?text.substring(0,109)+"...":text);cs.endText();y-=17;}}}doc.save(bytes);return bytes.toByteArray();}catch(IOException e){throw new IllegalStateException("Could not generate PDF",e);}}
 private String money(java.math.BigDecimal v){return "INR "+v.setScale(2,java.math.RoundingMode.HALF_UP);}
}
